import assert from "node:assert/strict";
import { createHash } from "node:crypto";
import { type ExerciseContext, exercises } from "./exercise";

export async function exerciseAssets(ctx: ExerciseContext) {
  const { check, value } = exercises(ctx);
  // Valid PNG fixture generated by sharp, a declared Marina dependency. No image model.
  const sharp = (await import("sharp")).default;
  const bytes = await sharp({
    create: { width: 8, height: 8, channels: 3, background: { r: 23, g: 137, b: 219 } },
  })
    .png()
    .toBuffer();
  const upload = new FormData();
  upload.append("file", new File([bytes], "qa-blue-square.png", { type: "image/png" }));
  const response = await ctx.request("/api/assets", { method: "POST", body: upload });
  const text = await response.text();
  assert.equal(response.status, 201, text);
  const asset = value("SELECT id FROM assets WHERE filename='qa-blue-square.png'");
  await ctx.scenario("asset:uploaded-bytes", async () => {
    const stored = ctx.db.query("SELECT sha256 FROM assets WHERE id=?").get(asset) as {
      sha256: string;
    };
    assert.equal(stored.sha256, createHash("sha256").update(bytes).digest("hex"));
    return "Multipart upload preserved independently hashed PNG bytes in the asset library.";
  });
  await check("asset list type:image", /qa-blue-square/, ["asset list "]);
  await check(`asset show ${asset}`, /qa-blue-square/, ["asset show "]);
  await check(`asset tag ${asset} +qa-blue`, /qa-blue/, ["asset tag "]);
  await check(
    `asset caption ${asset} -- qa-caption-blue-square-839`,
    /qa-caption-blue-square-839|caption/i,
    ["asset caption <id> -- "],
  );
  await check(`asset alt ${asset} -- A small blue qualification square`, /blue|alt/i, [
    "asset alt ",
  ]);
  await check("asset search qa-caption-blue-square-839", /qa-blue-square/, ["asset search "]);
  await check("canvas asset list", /qa-blue-square/, ["canvas asset list"]);
  await check(`canvas asset info ${asset}`, /qa-blue-square/, ["canvas asset info "]);
  await check("canvas create qa-media Media qualification", /created/i, ["canvas create "]);
  const canvas = value("SELECT id FROM canvases WHERE name='qa-media'");
  await check(`canvas publish image ${asset} qa-media`, /published|posted/i, ["canvas publish "]);
  for (const mode of ["complete", "complete-rich", "fail"]) {
    const result = await ctx.request(`/api/canvases/${canvas}/nodes`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        type: "text",
        data: {
          text: `qa-intent-${mode}`,
          intent: { status: "pending", prompt: `Check qa-intent-${mode}` },
        },
      }),
    });
    const node = (await result.json()) as { id: string };
    assert.equal(result.status, 201, JSON.stringify(node));
    await check("canvas intent list qa-media", /qa-intent/, ["canvas intent list "]);
    await check(`canvas intent claim ${node.id}`, /Claimed intent/, ["canvas intent claim "]);
    const payload =
      mode === "complete-rich"
        ? JSON.stringify({
            title: "Qualification",
            components: [{ id: "root", component: "Text", text: "qa-rich-result-143" }],
          })
        : "qa-result-143";
    await check(
      `canvas intent ${mode} ${node.id} ${payload}`,
      mode === "fail" ? /Intent failed/ : /Intent completed/,
      [`canvas intent ${mode} `],
      `SELECT 1 FROM canvas_nodes WHERE id='${node.id}' AND json_extract(data,'$.intent.status')='${mode === "fail" ? "failed" : "done"}'`,
    );
  }
  await check(
    `asset delete ${asset}`,
    /deleted|removed/i,
    ["asset delete "],
    `SELECT 1 WHERE NOT EXISTS(SELECT 1 FROM assets WHERE id='${asset}')`,
  );
  const duplicate = new FormData();
  duplicate.append("file", new File([bytes], "qa-blue-second.png", { type: "image/png" }));
  const second = await ctx.request("/api/assets", { method: "POST", body: duplicate });
  assert.equal(second.status, 201, await second.text());
  const id2 = value("SELECT id FROM assets WHERE filename='qa-blue-second.png'");
  await check(`canvas asset delete ${id2}`, /deleted|removed/i, ["canvas asset delete "]);
}

/** Guard precedes parsing and all these operations in the production handlers.
 * A proven missing provider is BLOCKED, never positive execution coverage. */
export async function exerciseSandboxPrerequisites(ctx: ExerciseContext) {
  for (const [prefix, input, expected, source] of [
    [
      "code project ",
      "code project init qa-sandbox-project",
      /No sandbox provider is configured; sandbox projects are unavailable/,
      "src/engine/commands/code/project.ts:29",
    ],
    [
      "code service ",
      "code service start qa-service -- bun app.ts",
      /No sandbox provider is configured; managed VM services are unavailable/,
      "src/engine/commands/code/service.ts:47",
    ],
  ] as const) {
    const commands = ctx.inventory.commands
      .flatMap((c) => c.forms ?? [])
      .filter((f) => f.syntax.startsWith(prefix))
      .map((f) => f.syntax);
    const output = await ctx.command("owner", input);
    ctx.record({
      id: `prerequisite:${prefix.trim().replaceAll(" ", "-")}`,
      status: expected.test(output) ? "blocked" : "failed",
      commands,
      detail: JSON.stringify({
        input,
        output,
        source,
        requires:
          "Configured sandbox provider. This guard dominates every operation in this handler; a text model does not supply a VM provider.",
        scope: "Admission test only; each listed operation remains unqualified.",
      }),
    });
  }
}
